import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';

function App() {
  const [user, setUser] = useState(null);
  const [page, setPage] = useState('login');
  const [emailInput, setEmailInput] = useState('');
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingItem, setEditingItem] = useState(null);
  const [formData, setFormData] = useState({});
  const [courses, setCourses] = useState([]);
  const [assignments, setAssignments] = useState([]);
  const [enrolledCourseIds, setEnrolledCourseIds] = useState([]);
  const [selectedAssignment, setSelectedAssignment] = useState(null);
  const [submissionText, setSubmissionText] = useState('');
  const [showFileModal, setShowFileModal] = useState(false);
  const [currentSubmissionText, setCurrentSubmissionText] = useState('');
  const [showGradeModal, setShowGradeModal] = useState(false);
  const [submissionToGrade, setSubmissionToGrade] = useState(null);
  const [gradeValue, setGradeValue] = useState('');
  const [feedbackText, setFeedbackText] = useState('');
  const [showConfirmDelete, setShowConfirmDelete] = useState(false);
  const [itemToDelete, setItemToDelete] = useState(null);
  const [allUsers, setAllUsers] = useState([]);
  const [showChat, setShowChat] = useState(false);
  const [chatMessages, setChatMessages] = useState([
    { sender: 'bot', text: "Hello! I'm your Student Portal assistant. Ask me anything about how to use the portal!" }
  ]);
  const [chatInput, setChatInput] = useState('');
  const [chatLoading, setChatLoading] = useState(false);
  const chatEndRef = useRef(null);

  const API = 'http://localhost:5000/api';

  const getEndpoint = (pageName) => {
    if (pageName === 'courses') return 'courses';
    if (pageName === 'assignments') return 'assignments';
    if (pageName === 'announcements') return 'announcements';
    if (pageName === 'submissions') return user?.role === 'student' ? `submissions?studentid=${user.id}` : 'submissions';
    if (pageName === 'instructors') return 'users?role=instructor';
    return null;
  };

  const getEmptyForm = (pageName) => {
    if (pageName === 'courses') return { title: '', description: '', syllabus: '' };
    if (pageName === 'assignments') return { title: '', duedate: '', description: '', courseid: '' };
    if (pageName === 'announcements') return { title: '', message: '', courseid: '' };
    if (pageName === 'instructors') return { name: '', email: '', courseTitle: '', courseDescription: '', courseSyllabus: '' };
    return {};
  };

  const login = async (e) => {
    e.preventDefault();
    if (!emailInput.trim()) return alert('Please enter your email');
    try {
      const res = await axios.post(`${API}/users/login`, { email: emailInput.trim() });
      setUser(res.data);
      setPage(res.data.role === 'admin' ? 'instructors' : 'courses');
    } catch (err) {
      alert('Login failed — user not found');
    }
  };

  const logout = () => {
    setUser(null);
    setPage('login');
    setEmailInput('');
    setData([]);
    setCourses([]);
    setAssignments([]);
    setEnrolledCourseIds([]);
    setSelectedAssignment(null);
    setSubmissionText('');
    setShowFileModal(false);
    setShowGradeModal(false);
    setAllUsers([]);
    setShowChat(false);
    setChatMessages([{ sender: 'bot', text: "Hello! I'm your Student Portal assistant. Ask me anything about how to use the portal!" }]);
  };

  const loadData = async () => {
    setLoading(true);
    try {
      const [coursesRes, assignmentsRes, usersRes] = await Promise.all([
        axios.get(`${API}/courses`),
        axios.get(`${API}/assignments`),
        user?.role === 'instructor' ? axios.get(`${API}/users`) : Promise.resolve({ data: [] })
      ]);
      setCourses(coursesRes.data);
      setAssignments(assignmentsRes.data);
      if (user?.role === 'instructor') setAllUsers(usersRes.data);

      const enrolled = coursesRes.data.filter(c => c.students?.includes(user?.id)).map(c => c.id);
      if (user?.role === 'student') setEnrolledCourseIds(enrolled);

      const endpoint = getEndpoint(page);
      if (endpoint) {
        const res = await axios.get(`${API}/${endpoint}`);
        let fetched = res.data;
        if (page === 'courses' && user?.role === 'instructor') {
          fetched = fetched.filter(c => c.instructorId === user.id);
        }
        setData(fetched);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (user && page !== 'login') loadData();
  }, [page, user]);

  const handleCreateOrUpdate = async () => {
    try {
      const base = page === 'instructors' ? 'users' : getEndpoint(page)?.split('?')[0];
      let payload = { ...formData };
      if (page === 'courses') payload.instructorid = user.id;

      let res;
      if (editingItem) {
        res = await axios.put(`${API}/${base}/${editingItem.id}`, payload);
      } else {
        res = await axios.post(`${API}/${base}`, payload);
      }

      if (page === 'instructors' && !editingItem) {
        await axios.post(`${API}/courses`, {
          title: formData.courseTitle,
          description: formData.courseDescription,
          syllabus: formData.courseSyllabus,
          instructorid: res.data.id
        });
      }

      setShowForm(false);
      loadData();
    } catch (err) {
      alert('Error saving');
    }
  };

  const editItem = (item) => {
    setEditingItem(item);
    setFormData(item);
    setShowForm(true);
  };

  const confirmDelete = async () => {
    try {
      const base = page === 'instructors' ? 'users' : getEndpoint(page)?.split('?')[0];
      await axios.delete(`${API}/${base}/${itemToDelete.id || itemToDelete}`);
      setShowConfirmDelete(false);
      setItemToDelete(null);
      loadData();
    } catch (err) {
      alert('Delete failed');
    }
  };

  const enrollInCourse = async (courseId) => {
    try {
      await axios.post(`${
API}/courses/${courseId}/enroll`, { studentid: user.id });
      loadData();
    } catch (err) {
      alert('Already enrolled');
    }
  };

  const dropCourse = async (courseId) => {
    try {
      await axios.post(`${API}/courses/${courseId}/drop`, { studentid: user.id });
      loadData();
    } catch (err) {
      alert('Error dropping');
    }
  };

  const submitAssignment = async () => {
    if (!submissionText.trim()) return alert('Please enter your answer');
    try {
      await axios.post(`${API}/submissions`, {
        assignmentid: selectedAssignment.id,
        studentid: user.id,
        fileurl: submissionText
      });
      setSubmissionText('');
      setSelectedAssignment(null);
      loadData();
    } catch (err) {
      alert('Submission failed');
    }
  };

  const gradeSubmission = async () => {
    try {
      await axios.put(`${API}/submissions/${submissionToGrade.id}/grade`, {
        grade: parseInt(gradeValue),
        feedback: feedbackText
      });
      setShowGradeModal(false);
      setGradeValue('');
      setFeedbackText('');
      loadData();
    } catch (err) {
      alert('Error grading');
    }
  };

  const getAssignmentTitle = (id) => assignments.find(a => a.id === id)?.title || `Assignment ${id}`;
  const getStudentName = (id) => allUsers.find(u => u.id === id)?.name || `Student ${id}`;

  const sendChatMessage = async () => {
    if (!chatInput.trim() || chatLoading) return;
    const msg = chatInput.trim();
    setChatMessages(prev => [...prev, { sender: 'user', text: msg }]);
    setChatInput('');
    setChatLoading(true);
    try {
      const res = await axios.post(`${API}/chat`, { message: msg });
      setChatMessages(prev => [...prev, { sender: 'bot', text: res.data.reply }]);
    } catch (err) {
      setChatMessages(prev => [...prev, { sender: 'bot', text: 'Sorry, I couldn\'t respond.' }]);
    } finally {
      setChatLoading(false);
      chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  };

  if (!user) {
    return (
      <div style={{ minHeight: '100vh', background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)', display: 'flex', justifyContent: 'center', alignItems: 'center', padding: '20px' }}>
        <div style={{ background: 'white', padding: '40px 50px', borderRadius: '16px', boxShadow: '0 20px 40px rgba(0,0,0,0.2)', maxWidth: '420px', width: '100%', textAlign: 'center' }}>
          <h1 style={{ margin: '0 0 30px', color: '#4a5568', fontSize: '2.5rem', fontWeight: '700' }}>Student Portal</h1>
          <form onSubmit={login}>
            <input type="email" placeholder="Enter your email" value={emailInput} onChange={(e) => setEmailInput(e.target.value)} required style={{ width: '100%', padding: '14px', margin: '10px 0', borderRadius: '8px', border: '2px solid #e2e8f0', fontSize: '1rem' }} />
            <button type="submit" style={{ width: '100%', padding: '14px', background: '#667eea', color: 'white', border: 'none', borderRadius: '8px', fontSize: '1.1rem', fontWeight: '600', cursor: 'pointer', marginTop: '10px' }}>Login</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div style={{ minHeight: '100vh', background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)', fontFamily: '"Segoe UI", Roboto, sans-serif', color: '#333' }}>
      <header style={{ background: 'rgba(255,255,255,0.95)', backdropFilter: 'blur(10px)', padding: '15px 30px', boxShadow: '0 4px 20px rgba(0,0,0,0.1)', position: 'sticky', top: 0, zIndex: 1000 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', maxWidth: '1400px', margin: '0 auto' }}>
          <h1 style={{ margin: 0, color: '#4a5568', fontSize: '1.8rem' }}>Student Portal</h1>
          <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
            <span style={{ color: '#718096', fontWeight: '500' }}>Welcome, <strong>{user.name}</strong> ({user.role})</span>
            <button onClick={logout} style={{ padding: '10px 20px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>Logout</button>
          </div>
        </div>
      </header>

      <nav style={{ background: '#4a5568', padding: '15px 30px', boxShadow: '0 4px 15px rgba(0,0,0,0.1)' }}>
        <div style={{ maxWidth: '1400px', margin: '0 auto', display: 'flex', gap: '15px', flexWrap: 'wrap' }}>
          {(user.role === 'student' || user.role === 'instructor') && <button onClick={() => setPage('courses')} style={{ padding: '12px 24px', background: page === 'courses' ? '#667eea' : '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>Courses</button>}
          {user.role === 'student' && (
            <>
              <button onClick={() => setPage('assignments')} style={{ padding: '12px 24px', background: page === 'assignments' ? '#667eea' : '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>Assignments</button>
              <button onClick={() => setPage('announcements')} style={{ padding: '12px 24px', background: page === 'announcements' ? '#667eea' : '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>Announcements</button>
              <button onClick={() => setPage('submissions')} style={{ padding: '12px 24px', background: page === 'submissions' ? '#667eea' : '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>My Submissions</button>
            </>
          )}
          {user.role === 'instructor' && (
            <>
              <button onClick={() => setPage('assignments')} style={{ padding: '12px 24px', background: page === 'assignments' ? '#667eea' : '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>Assignments</button>
              <button onClick={() => setPage('announcements')} style={{ padding: '12px 24px', background: page === 'announcements' ? '#667eea' : '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>Announcements</button>
              <button onClick={() => setPage('submissions')} style={{ padding: '12px 24px', background: page === 'submissions' ? '#667eea' : '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>Grade Submissions</button>
            </>
          )}
          {user.role === 'admin' && (
            <button onClick={() => setPage('instructors')} style={{ padding: '12px 24px', background: page === 'instructors' ? '#667eea' : '#718096', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>Manage Instructors</button>
          )}
        </div>
      </nav>

      <main style={{ maxWidth: '1400px', margin: '30px auto', padding: '0 20px' }}>
        <div style={{ background: 'white', borderRadius: '16px', boxShadow: '0 10px 30px rgba(0,0,0,0.1)', padding: '30px', minHeight: '600px' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '30px' }}>
            <h2 style={{ margin: 0, color: '#2d3748', fontSize: '2rem' }}>{page.charAt(0).toUpperCase() + page.slice(1)}</h2>
            {(user.role === 'instructor' && ['courses', 'assignments', 'announcements'].includes(page)) || (user.role === 'admin' && page === 'instructors') ? (
              <button onClick={() => { setEditingItem(null); setFormData(getEmptyForm(page)); setShowForm(true); }} style={{ padding: '12px 24px', background: '#667eea', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>
                + Add New {page === 'instructors' ? 'Instructor' : page.slice(0, -1)}
              </button>
            ) : null}
          </div>

          {loading && <p style={{ textAlign: 'center', color: '#718096' }}>Loading...</p>}

          {/* Courses Table */}
          {page === 'courses' && data.length > 0 && (
            <table style={{ width: '100%', borderCollapse: 'collapse' }}>
              <thead><tr style={{ background: '#f7fafc' }}>
                <th style={{ padding: '16px', textAlign: 'left' }}>Title</th>
                <th style={{ padding: '16px', textAlign: 'left' }}>Description</th>
                <th style={{ padding: '16px', textAlign: 'left' }}>Syllabus</th>
                <th style={{ padding: '16px', textAlign: 'left' }}>Action</th>
              </tr></thead>
              <tbody>
                {data.map(course => (
                  <tr key={course.id}>
                    <td style={{ padding: '16px' }}>{course.title}</td>
                    <td style={{ padding: '16px' }}>{course.description || '—'}</td>
                    <td style={{ padding: '16px' }}>{course.syllabus || '—'}</td>
                    <td style={{ padding: '16px' }}>
                      {user.role === 'student' ? (
                        enrolledCourseIds.includes(course.id) ? (
                          <button onClick={() => dropCourse(course.id)} style={{ padding: '10px 20px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '8px' }}>Drop</button>
                        ) : (
                          <button onClick={() => enrollInCourse(course.id)} style={{ padding: '10px 20px', background: '#48bb78', color: 'white', border: 'none', borderRadius: '8px' }}>Enroll</button>
                        )
                      ) : (
                        <div style={{ display: 'flex', gap: '8px' }}>
                          <button onClick={() => editItem(course)} style={{ padding: '8px 16px', background: '#3182ce', color: 'white', border: 'none', borderRadius: '6px' }}>Edit</button>
                          <button onClick={() => { setItemToDelete(course); setShowConfirmDelete(true); }} style={{ padding: '8px 16px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '6px' }}>Delete</button>
                        </div>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}

          {/* Submissions Table with Names/Titles */}
          {page === 'submissions' && data.length > 0 && (
            <table style={{ width: '100%', borderCollapse: 'collapse' }}>
              <thead><tr style={{ background: '#f7fafc' }}>
                {user.role === 'student' && <><th style={{ padding: '16px', textAlign: 'left' }}>Assignment</th><th style={{ padding: '16px', textAlign: 'left' }}>Your Answer</th><th style={{ padding: '16px', textAlign: 'left' }}>Grade</th></>}
                {user.role === 'instructor' && <><th style={{ padding: '16px', textAlign: 'left' }}>Student</th><th style={{ padding: '16px', textAlign: 'left' }}>Assignment</th><th style={{ padding: '16px', textAlign: 'left' }}>Answer</th><th style={{ padding: '16px', textAlign: 'left' }}>Grade</th></>}
                <th style={{ padding: '16px', textAlign: 'left' }}>Actions</th>
              </tr></thead>
              <tbody>
                {data.map(sub => (
                  <tr key={sub.id}>
                    {user.role === 'student' && <><td style={{ padding: '16px' }}>{getAssignmentTitle(sub.assignmentid)}</td>
                    <td style={{ padding: '16px' }}>{sub.fileurl ? 'Submitted' : 'Not submitted'}</td>
                    <td style={{ padding: '16px', color: sub.grade !== null ? '#48bb78' : '#718096' }}>{sub.grade !== null ? `${sub.grade}/100` : 'Not graded'}</td></>}
                    {user.role === 'instructor' && <><td style={{ padding: '16px' }}>{getStudentName(sub.studentid)}</td>
                    <td style={{ padding: '16px' }}>{getAssignmentTitle(sub.assignmentid)}</td>
                    <td style={{ padding: '16px' }}>{sub.fileurl ? <button onClick={() => { setCurrentSubmissionText(sub.fileurl); setShowFileModal(true); }} style={{ background: '#3182ce', color: 'white', padding: '6px 12px', border: 'none', borderRadius: '4px' }}>View</button> : '—'}</td>
                    <td style={{ padding: '16px', color: sub.grade !== null ? '#48bb78' : '#718096' }}>{sub.grade !== null ? `${sub.grade}/100` : '—'}</td></>}
                    <td style={{ padding: '16px' }}>
                      <button onClick={() => { setSubmissionToGrade(sub); setGradeValue(sub.grade || ''); setFeedbackText(sub.feedback || ''); setShowGradeModal(true); }} style={{ padding: '8px 16px', background: sub.grade === null ? '#48bb78' : '#ed8936', color: 'white', border: 'none', borderRadius: '6px' }}>
                        {sub.grade === null ? 'Grade' : 'Regrade'}
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}

          {/* Instructors Table for Admin */}
          {page === 'instructors' && data.length > 0 && (
            <table style={{ width: '100%', borderCollapse: 'collapse' }}>
              <thead><tr style={{ background: '#f7fafc' }}>
                <th style={{ padding: '16px', textAlign: 'left' }}>Name</th>
                <th style={{ padding: '16px', textAlign: 'left' }}>Email</th>
                <th style={{ padding: '16px', textAlign: 'left' }}>Actions</th>
              </tr></thead>
              <tbody>
                {data.map(inst => (
                  <tr key={inst.id}>
                    <td style={{ padding: '16px' }}>{inst.name}</td>
                    <td style={{ padding: '16px' }}>{inst.email}</td>
                    <td style={{ padding: '16px' }}>
                      <button onClick={() => editItem(inst)} style={{ padding: '8px 16px', background: '#3182ce', color: 'white', border: 'none', borderRadius: '6px', marginRight: '8px' }}>Edit</button>
                      <button onClick={() => { setItemToDelete(inst); setShowConfirmDelete(true); }} style={{ padding: '8px 16px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '6px' }}>Delete</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}

          {/* Modals - Full Implementation */}
          {showForm && (
            <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
              <div style={{ background: 'white', borderRadius: '16px', padding: '30px', width: '90%', maxWidth: '550px', boxShadow: '0 20px 50px rgba(0,0,0,0.3)' }}>
                <h3 style={{ marginTop: 0, color: '#2d3748' }}>{editingItem ? 'Edit' : 'Add'} {page === 'instructors' ? 'Instructor' : page.slice(0, -1)}</h3>
                <form onSubmit={(e) => { e.preventDefault(); handleCreateOrUpdate(); }}>
                  {/* Common Fields */}
                  <input type="text" placeholder={page === 'courses' || page === 'assignments' || page === 'announcements' ? 'Title' : 'Name'} value={formData.title || formData.name || ''} onChange={(e) => setFormData({ ...formData, title: e.target.value, name: e.target.value })} style={{ width: '100%', padding: '12px', margin: '10px 0', borderRadius: '8px', border: '2px solid #e2e8f0' }} required />
                  {(page === 'courses' || page === 'assignments' || page === 'announcements') && (
                    <textarea placeholder="Description/Message" value={formData.description || formData.message || ''} onChange={(e) => setFormData({ ...formData, description: e.target.value, message: e.target.value })} style={{ width: '100%', padding: '12px', margin: '10px 0', borderRadius: '8px', border: '2px solid #e2e8f0', minHeight: '100px' }} />
                  )}
                  {page === 'courses' && <textarea placeholder="Syllabus" value={formData.syllabus || ''} onChange={(e) => setFormData({ ...formData, syllabus: e.target.value })} style={{ width: '100%', padding: '12px', margin: '10px 0', borderRadius: '8px', border: '2px solid #e2e8f0', minHeight: '100px' }} />}
                  {page === 'instructors' && <input type="email" placeholder="Email" value={formData.email || ''} onChange={(e) => setFormData({ ...formData, email: e.target.value })} style={{ width: '100%', padding: '12px', margin: '10px 0', borderRadius: '8px', border: '2px solid #e2e8f0' }} required />}
                  {page === 'instructors' && !editingItem && (
                    <>
                      <input type="text" placeholder="Course Title" value={formData.courseTitle || ''} onChange={(e) => setFormData({ ...formData, courseTitle: e.target.value })} style={{ width: '100%', padding: '12px', margin: '10px 0', borderRadius: '8px', border: '2px solid #e2e8f0' }} required />
                      <textarea placeholder="Course Description" value={formData.courseDescription || ''} onChange={(e) => setFormData({ ...formData, courseDescription: e.target.value })} style={{ width: '100%', padding: '12px', margin: '10px 0', borderRadius: '8px', border: '2px solid #e2e8f0', minHeight: '80px' }} />
                      <textarea placeholder="Course Syllabus" value={formData.courseSyllabus || ''} onChange={(e) => setFormData({ ...formData, courseSyllabus: e.target.value })} style={{ width: '100%', padding: '12px', margin: '10px 0', borderRadius: '8px', border: '2px solid #e2e8f0', minHeight: '80px' }} />
                    </>
                  )}
                  {(page === 'assignments' || page === 'announcements') && (
                    <select value={formData.courseid || ''} onChange={(e) => setFormData({ ...formData, courseid: e.target.value })} style={{ width: '100%', padding: '12px', margin: '10px 0', borderRadius: '8px', border: '2px solid #e2e8f0' }} required>
                      <option value="">Select Course</option>
                      {courses.map(c => <option key={c.id} value={c.id}>{c.title}</option>)}
                    </select>
                  )}
                  {page === 'assignments' && <input type="date" value={formData.duedate || ''} onChange={(e) => setFormData({ ...formData, duedate: e.target.value })} style={{ width: '100%', padding: '12px', margin: '10px 0', borderRadius: '8px', border: '2px solid #e2e8f0' }} />}
                  <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px', marginTop: '20px' }}>
                    <button type="submit" style={{ padding: '12px 28px', background: '#48bb78', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>Save</button>
                    <button type="button" onClick={() => setShowForm(false)} style={{ padding: '12px 28px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600' }}>Cancel</button>
                  </div>
                </form>
              </div>
            </div>
          )}

          {selectedAssignment && user.role === 'student' && (
            <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
              <div style={{ background: 'white', borderRadius: '16px', padding: '30px', width: '90%', maxWidth: '600px', boxShadow: '0 20px 50px rgba(0,0,0,0.3)' }}>
                <h3 style={{ marginTop: 0, color: '#2d3748' }}>Submit: {selectedAssignment.title}</h3>
                <p><strong>Description:</strong> {selectedAssignment.description || '—'}</p>
                <p><strong>Due:</strong> {selectedAssignment.duedate || 'No due date'}</p>
                <textarea value={submissionText} onChange={(e) => setSubmissionText(e.target.value)} placeholder="Your answer..." rows="10" style={{ width: '100%', padding: '16px', borderRadius: '8px', border: '2px solid #e2e8f0' }} required />
                <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px', marginTop: '20px' }}>
                  <button onClick={submitAssignment} style={{ padding: '12px 28px', background: '#48bb78', color: 'white', border: 'none', borderRadius: '8px' }}>Submit</button>
                  <button onClick={() => { setSelectedAssignment(null); setSubmissionText(''); }} style={{ padding: '12px 28px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '8px' }}>Cancel</button>
                </div>
              </div>
            </div>
          )}

          {showFileModal && (
            <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
              <div style={{ background: 'white', borderRadius: '16px', padding: '30px', width: '90%', maxWidth: '700px', maxHeight: '90vh', overflow: 'auto', boxShadow: '0 20px 50px rgba(0,0,0,0.3)' }}>
                <h3 style={{ marginTop: 0, color: '#2d3748' }}>Submission</h3>
                <div style={{ background: '#f8fafc', padding: '20px', borderRadius: '12px', whiteSpace: 'pre-wrap' }}>{currentSubmissionText || 'No content'}</div>
                <button onClick={() => setShowFileModal(false)} style={{ marginTop: '20px', padding: '12px 28px', background: '#718096', color: 'white', border: 'none', borderRadius: '8px' }}>Close</button>
              </div>
            </div>
          )}

          {showGradeModal && submissionToGrade && (
            <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
              <div style={{ background: 'white', borderRadius: '16px', padding: '30px', width: '90%', maxWidth: '700px', boxShadow: '0 20px 50px rgba(0,0,0,0.3)' }}>
                <h3 style={{ marginTop: 0, color: '#2d3748' }}>Grade Submission</h3>
                <p><strong>Student:</strong> {getStudentName(submissionToGrade.studentid)}</p>
                <p><strong>Assignment:</strong> {getAssignmentTitle(submissionToGrade.assignmentid)}</p>
                <div style={{ background: '#f8fafc', padding: '20px', borderRadius: '12px', margin: '15px 0' }}>
                  <strong>Answer:</strong><div style={{ marginTop: '10px', whiteSpace: 'pre-wrap' }}>{submissionToGrade.fileurl || 'No submission'}</div>
                </div>
                <input type="number" min="0" max="100" value={gradeValue} onChange={(e) => setGradeValue(e.target.value)} placeholder="Grade" style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '2px solid #e2e8f0', margin: '10px 0' }} />
                <textarea value={feedbackText} onChange={(e) => setFeedbackText(e.target.value)} placeholder="Feedback" rows="4" style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '2px solid #e2e8f0' }} />
                <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px', marginTop: '20px' }}>
                  <button onClick={gradeSubmission} style={{ padding: '12px 28px', background: '#48bb78', color: 'white', border: 'none', borderRadius: '8px' }}>Save</button>
                  <button onClick={() => { setShowGradeModal(false); setSubmissionToGrade(null); }} style={{ padding: '12px 28px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '8px' }}>Cancel</button>
                </div>
              </div>
            </div>
          )}

          {showConfirmDelete && (
            <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 1000 }}>
              <div style={{ background: 'white', borderRadius: '16px', padding: '30px', textAlign: 'center', boxShadow: '0 20px 50px rgba(0,0,0,0.3)' }}>
                <h3 style={{ margin: '0 0 20px', color: '#2d3748' }}>Confirm Delete</h3>
                <p style={{ margin: '0 0 30px', color: '#718096' }}>Are you sure?</p>
                <div style={{ display: 'flex', justifyContent: 'center', gap: '15px' }}>
                  <button onClick={confirmDelete} style={{ padding: '12px 28px', background: '#e53e3e', color: 'white', border: 'none', borderRadius: '8px' }}>Yes</button>
                  <button onClick={() => setShowConfirmDelete(false)} style={{ padding: '12px 28px', background: '#718096', color: 'white', border: 'none', borderRadius: '8px' }}>Cancel</button>
                </div>
              </div>
            </div>
          )}

          {/* AI Chat */}
          <button onClick={() => setShowChat(!showChat)} style={{ position: 'fixed', bottom: '30px', right: '30px', width: '60px', height: '60px', background: '#667eea', color: 'white', border: 'none', borderRadius: '50%', fontSize: '28px', cursor: 'pointer', boxShadow: '0 8px 25px rgba(0,0,0,0.3)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>AI</button>
          {showChat && (
            <div style={{ position: 'fixed', bottom: '100px', right: '30px', width: '380px', height: '500px', background: 'white', borderRadius: '16px', boxShadow: '0 20px 50px rgba(0,0,0,0.3)', display: 'flex', flexDirection: 'column', zIndex: 1000 }}>
              <div style={{ padding: '16px', background: '#667eea', color: 'white', borderRadius: '16px 16px 0 0', fontWeight: '600', fontSize: '1.1rem', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                NM Portal Assistant
                <button onClick={() => setShowChat(false)} style={{ background: 'none', border: 'none', color: 'white', fontSize: '24px', cursor: 'pointer' }}>×</button>
              </div>
              <div style={{ flex: 1, padding: '16px', overflowY: 'auto', background: '#f8fafc' }}>
                {chatMessages.map((msg, i) => (
                  <div key={i} style={{ margin: '10px 0', textAlign: msg.sender === 'user' ? 'right' : 'left' }}>
                    <div style={{ display: 'inline-block', maxWidth: '80%', padding: '12px 16px', borderRadius: '16px', background: msg.sender === 'user' ? '#667eea' : '#e2e8f0', color: msg.sender === 'user' ? 'white' : '#333' }}>
                      {msg.text}
                    </div>
                  </div>
                ))}
                {chatLoading && <div style={{ textAlign: 'left' }}><div style={{ display: 'inline-block', padding: '12px 16px', background: '#e2e8f0', borderRadius: '16px' }}>Thinking...</div></div>}
                <div ref={chatEndRef} />
              </div>
              <div style={{ padding: '16px', borderTop: '1px solid #e2e8f0', display: 'flex' }}>
                <input type="text" value={chatInput} onChange={(e) => setChatInput(e.target.value)} onKeyPress={(e) => e.key === 'Enter' && sendChatMessage()} placeholder="Ask about the portal..." style={{ flex: 1, padding: '12px', borderRadius: '8px', border: '2px solid #e2e8f0', fontSize: '1rem' }} />
                <button onClick={sendChatMessage} disabled={chatLoading} style={{ marginLeft: '10px', padding: '12px 20px', background: '#667eea', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Send</button>
              </div>
            </div>
          )}
        </div>
      </main>

      <footer style={{ textAlign: 'center', padding: '30px', color: 'white', background: 'rgba(0,0,0,0.3)', marginTop: '50px' }}>
        <h3 style={{ margin: '0 0 10px' }}>Student Portal © 2025</h3>
        <p style={{ margin: 0, opacity: 0.9 }}>Nikko Manuel - Marlon Chipa Learning Management System</p>
      </footer>
    </div>
  );
}

export default App;
